CREATE TABLE whatsapp_reminders (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, kind VARCHAR(16) NOT NULL, ref VARCHAR(120) NOT NULL, order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, status VARCHAR(16) NOT NULL, channel VARCHAR(16) NULL, error VARCHAR(500) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), resolved_at DATETIME(6) NULL, PRIMARY KEY (id), UNIQUE KEY whatsapp_reminders_ref_uq (user_id,ref), KEY whatsapp_reminders_open_idx (status,created_at), CONSTRAINT whatsapp_reminders_kind_ck CHECK (kind IN ('unconfirmed','abandoned')), CONSTRAINT whatsapp_reminders_status_ck CHECK (status IN ('sent','skipped','failed','answered','no_answer')), CONSTRAINT whatsapp_reminders_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_reminders_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci